      (activeCount === 1 ? 'item' : 'items') + ' left';

    // Toggle all
    var allCompleted = model.todos.length > 0 && model.todos.every(function (t) { return t.completed; });
    this.toggleAll.checked = allCompleted;

    // Clear completed
    var completedCount = model.todos.filter(function (t) { return t.completed; }).length;
    this.clearCompleted.style.display = completedCount > 0 ? '' : 'none';

    // Active filter link
    var filterLinks = this.filters.querySelectorAll('a');
    filterLinks.forEach(function (link) {
      var href = link.getAttribute('href').replace('#/', '') || 'all';
      if (href === self.controller.filter) {
        link.classList.add('selected');
      } else {
        link.classList.remove('selected');
      }
    });
  };

  TodoView.prototype.escapeHtml = function (text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  };

  // ---- Bootstrap ----

  window.appState = {};

  document.addEventListener('DOMContentLoaded', function () {
    var model = new TodoModel(STORAGE_KEY);
    var controller = new TodoController(model);
    var view = new TodoView(controller);

    // Set initial filter from URL
    var hash = window.location.hash.replace('#/', '') || 'all';
    controller.filter = hash;
    view.render();

    window.appState.model = model;
    window.appState.controller = controller;
    window.appState.view = view;
  });
})();
